#!/usr/bin/env bash
# Test-only offline ACME double. Never included in a production image.
set -euo pipefail
args=("$@")
config="" alias="" domains=() register=0
while (($#)); do
 case "$1" in
  --config) config="$2"; shift 2;;
  --alias) alias="$2"; shift 2;;
  --domain) domains+=("$2"); shift 2;;
  --register) register=1; shift;;
  *) shift;;
 esac
done
# Generated by certctl, not untrusted remote input.
source "$config"
if [[ "$register" == 1 ]]; then
 mkdir -p "$ACCOUNTDIR"
 echo account >"$ACCOUNTDIR/test-account"
 echo register >>"$LITEEDGE_HA_DIR/acme/test-invocations"
 exit 0
fi
[[ -f "$ACCOUNTDIR/test-account" ]]
echo issue >>"$LITEEDGE_HA_DIR/acme/test-invocations"
token=offline-test-challenge
printf 'offline-proof' >"$WELLKNOWN/$token"
trap 'rm -f "$WELLKNOWN/$token"' EXIT
# Challenge must be available through BOTH independent NGINX runtimes.
for peer in $TEST_ACME_PEERS; do
 [[ "$(curl -fsS --max-time 3 -H "Host: ${domains[0]}" "http://$peer:8080/.well-known/acme-challenge/$token")" == offline-proof ]]
done
san=$(printf 'DNS:%s,' "${domains[@]}")
mkdir -p "$CERTDIR/$alias"
days=90
[[ "$(grep -c '^issue$' "$LITEEDGE_HA_DIR/acme/test-invocations")" != 1 ]] || days=2
openssl req -x509 -newkey rsa:2048 -nodes -days "$days" -keyout "$CERTDIR/$alias/privkey.pem" -out "$CERTDIR/$alias/fullchain.pem" -subj "/CN=${domains[0]}" -addext "subjectAltName=${san%,}" >/dev/null 2>&1
